-- diveday:allow-destructive drop-table tips: a tip is now a booking_checkouts row with purpose = 'tip' (issue #2718); every tip is copied there first with its id, and the previous release only fails a tip started or settled during the deploy itself, which Stripe redelivers; pre-pilot, no users (H-20260815-no-legacy)
-- diveday:allow-destructive drop-type tip_status: only tips.status used it, dropped above in this migration (issue #2718)
CREATE TYPE "checkout_purpose" AS ENUM('fare', 'tip');--> statement-breakpoint
ALTER TABLE "booking_checkouts" ADD COLUMN "purpose" "checkout_purpose" DEFAULT 'fare'::"checkout_purpose" NOT NULL;--> statement-breakpoint
ALTER TABLE "booking_checkouts" ADD CONSTRAINT "booking_checkouts_tip_shape" CHECK ("purpose" <> 'tip' or (not "is_deposit" and "promo_code_id" is null and "trip_promo_id" is null and "applied_discount_percent" is null and "applied_discount_cents" is null and not "tax_enabled" and "pass_through_cents" = 0));--> statement-breakpoint
INSERT INTO "booking_checkouts" ("id", "shop_id", "trip_id", "status", "purpose", "stripe_account_id", "stripe_session_id", "stripe_customer_id", "stripe_payment_intent_id", "checkout_url", "currency", "amount_per_diver_cents", "total_cents", "settled_total_cents", "expires_at", "completed_at", "created_at") SELECT "tips"."id", "tips"."shop_id", "bookings"."trip_id", CASE "tips"."status" WHEN 'paid' THEN 'completed'::"checkout_status" WHEN 'expired' THEN 'expired'::"checkout_status" ELSE 'pending'::"checkout_status" END, 'tip', "tips"."stripe_account_id", "tips"."stripe_session_id", "tips"."stripe_customer_id", "tips"."stripe_payment_intent_id", "tips"."checkout_url", "tips"."currency", "tips"."amount_cents", "tips"."amount_cents", CASE WHEN "tips"."status" = 'paid' THEN "tips"."amount_cents" END, "tips"."expires_at", "tips"."completed_at", "tips"."created_at" FROM "tips" INNER JOIN "bookings" ON "bookings"."id" = "tips"."booking_id";--> statement-breakpoint
INSERT INTO "booking_checkout_bookings" ("shop_id", "checkout_id", "booking_id") SELECT "shop_id", "id", "booking_id" FROM "tips";--> statement-breakpoint
DROP TABLE "tips";--> statement-breakpoint
DROP TYPE "tip_status";
